beatmap = json.loads((PROJECT/'generated/beatmap.json').read_text(encoding='utf-8'))
beatframes = sorted({round(s*24)+1 for bar in beatmap['bars'] for s in bar['beats']})
nearest = lambda frame: min(beatframes, key=lambda candidate: abs(candidate-frame))
# Correct ecosystem ordering; derive internal montage cuts from the DAW beat grid.
