items = []
for n,(name,option,start,end,worker,refs,scene) in enumerate(rows,1):
    prompt = 'Use case: illustration-story. Asset: one clean cinematic 16:9 music-video storyboard still.\nSHOT: '+scene+'\nREFERENCE ROLES: '+', '.join(refs.split(','))+'; use them for identity/design/style, not to duplicate their framing.\n\n'+LOCK+'\n'
